double I3m1a(double s1, double s2, double s3, double rtmdel) {
    using namespace constants_mod;

    double d1 = s1 - s2 - s3;
    double d2 = s2 - s3 - s1;
    double d3 = s3 - s1 - s2;

    double arg1 = 2 * std::atan(rtmdel / d1);
    double arg2 = 2 * std::atan(rtmdel / d2);
    double arg3 = 2 * std::atan(rtmdel / d3);
    return 2 / rtmdel * (dclaus(arg1) + dclaus(arg2) + dclaus(arg3));
}

std::complex<double> I3m1b(double s1, double s2, double s3, double rtdel, double flag) {
    using namespace constants_mod;

    std::complex<double> result;
    double d3 = s3 - s1 - s2;
    double x = s1 / s3;
    double y = s2 / s3;
    double rat = 0.5 * (d3 + rtdel) / s3;

    if (std::abs(rat) < 1.e-3) rat = 2.0 * s1 * s2 / (s3 * (d3 - rtdel));
    double rho = 1.0 / rat;
    double argx = rho * x;
    double argy = rho * y;
    double argdlx = -argx;
    double argdly = -argy;

    if ((argdlx > 1.0) || (argdly > 1.0)) {
        std::cerr << "Problems with call of I3m1b" << std::endl;
        std::cerr << "argdlx: " << argdlx << std::endl;
        std::cerr << "argdly: " << argdly << std::endl;
        std::exit(1);
    }

    double xlog = std::log(std::abs(argx));
    double ylog = std::log(std::abs(argy));
    double temp = xlog * ylog + pisq / 3.0 + (ylog - xlog) * std::log((1.0 + argy) / (1.0 + argx)) +
                 2 * (ddilog(argdlx) + ddilog(argdly));
    result = cplx1(temp - std::abs(flag) * pisq) + impi * cplx1(flag * (xlog + ylog));
    return -result / cplx1(rtdel);
}

