std::complex<double> L0(double x, double y) {
  double denom = one - x / y;
  if (std::abs(denom) < 1e-7) {
    return -cone - cplx1(denom * (half + denom / three));
  } else {
    return lnrat(x, y) / cplx1(denom);
  }
}

std::complex<double> L1(double x, double y) {
  double denom = one - x / y;
  if (std::abs(denom) < 1e-7) {
    return -half * cone - cplx1(denom / three * (one + 0.75 * denom));
  } else {
    return (L0(x, y) + cone) / cplx1(denom);
  }
}

std::complex<double> L2(double x, double y) {
  double r = x / y;
  double denom = one - r;
  if (std::abs(denom) < 1e-7) {
    return (cplx1(10.0) + denom * (cplx1(15.0) + cplx1(18.0) * denom)) /
           cplx1(60.0);
  } else {
    return (lnrat(x, y) - cplx1(half * (r - one / r))) /
           std::pow(cplx1(denom), 3);
  }
}

std::complex<double> L0old(double x, double y) {
  double denom = one - x / y;
  return lnrat(x, y) / cplx1(denom);
}

std::complex<double> L1old(double x, double y) {
  double denom = one - x / y;
  return (L0old(x, y) + cone) / cplx1(denom);
}

std::complex<double> Lsm1(double x1, double y1, double x2, double y2) {
  double r1 = x1 / y1;
  double r2 = x2 / y2;
  double omr1 = one - r1;
  double omr2 = one - r2;
  std::complex<double> dilog1, dilog2;

  if (omr1 > one) {
    dilog1 = cplx1(pisqo6 - ddilog(r1)) - lnrat(x1, y1) * cplx1(std::log(omr1));
  } else {
    dilog1 = cplx1(ddilog(omr1));
  }

  if (omr2 > one) {
    dilog2 = cplx1(pisqo6 - ddilog(r2)) - lnrat(x2, y2) * cplx1(std::log(omr2));
  } else {
    dilog2 = cplx1(ddilog(omr2));
  }

  return dilog1 + dilog2 + lnrat(x1, y1) * lnrat(x2, y2) - cplx1(pisqo6);
}

