import re

TOKEN_RE = re.compile(r"""
    \s*(?:
      (?P<NUM>\d+\.\d*(_dp)?|\.\d+(_dp)?|\d+_dp|\d+)
    | (?P<POW>\*\*)
    | (?P<ID>[A-Za-z_][A-Za-z_0-9]*)
    | (?P<LP>\()
    | (?P<RP>\))
    | (?P<COMMA>,)
    | (?P<MUL>\*)
    | (?P<DIV>/)
    | (?P<PLUS>\+)
    | (?P<MINUS>-)
    )
""", re.VERBOSE)

def tokenize(s):
    pos = 0
    toks = []
    while pos < len(s):
        m = TOKEN_RE.match(s, pos)
        if not m or m.end() == pos:
            if s[pos:].strip() == "":
                break
            raise ValueError(f"tokenize failure at {pos}: {s[pos:pos+30]!r}")
        pos = m.end()
        kind = m.lastgroup
        text = m.group(kind)
        toks.append((kind, text))
    return toks

class Parser:
    def __init__(self, toks):
        self.toks = toks
        self.i = 0
    def peek(self):
        return self.toks[self.i] if self.i < len(self.toks) else (None, None)
    def next(self):
        t = self.peek()
        self.i += 1
        return t
    def expect(self, kind):
        t = self.next()
        if t[0] != kind:
            raise ValueError(f"expected {kind} got {t} at pos {self.i}")
        return t

    def parse_expr(self):
        node = self.parse_term()
        while self.peek()[0] in ('PLUS','MINUS'):
            op = self.next()[0]
            rhs = self.parse_term()
            node = ('bin', '+' if op=='PLUS' else '-', node, rhs)
        return node

    def parse_term(self):
        node = self.parse_unary()
        while self.peek()[0] in ('MUL','DIV'):
            op = self.next()[0]
            rhs = self.parse_unary()
            node = ('bin', '*' if op=='MUL' else '/', node, rhs)
        return node

    def parse_unary(self):
        if self.peek()[0] in ('PLUS','MINUS'):
            op = self.next()[0]
            node = self.parse_unary()
            if op == 'MINUS':
                return ('neg', node)
            return node
        return self.parse_power()

    def parse_power(self):
        base = self.parse_primary()
        if self.peek()[0] == 'POW':
            self.next()
            exp = self.parse_unary()
            return ('pow', base, exp)
        return base

    def parse_primary(self):
        kind, text = self.peek()
        if kind == 'NUM':
            self.next()
            return ('num', text)
        if kind == 'ID':
            self.next()
            name = text
            if self.peek()[0] == 'LP':
                self.next()
                args = []
                if self.peek()[0] != 'RP':
                    args.append(self.parse_expr())
                    while self.peek()[0] == 'COMMA':
                        self.next()
                        args.append(self.parse_expr())
                self.expect('RP')
                return ('call', name, args)
            return ('id', name)
        if kind == 'LP':
            self.next()
            node = self.parse_expr()
            self.expect('RP')
            return ('paren', node)
        raise ValueError(f"unexpected token {kind,text} at {self.i}")

def parse(s):
    toks = tokenize(s)
    p = Parser(toks)
    node = p.parse_expr()
    if p.i != len(toks):
        raise ValueError(f"trailing tokens: {toks[p.i:]}")
    return node

def fmt_num(text):
    if text.endswith('_dp'):
        text = text[:-3]
    if text.endswith('.'):
        text = text + '0'
    return text

def codegen(node):
    kind = node[0]
    if kind == 'num':
        return fmt_num(node[1])
    if kind == 'id':
        return node[1]
    if kind == 'call':
        name = node[1]
        args = ", ".join(codegen(a) for a in node[2])
        return f"{name}({args})"
    if kind == 'paren':
        return f"({codegen(node[1])})"
    if kind == 'neg':
        return f"(-{codegen(node[1])})"
    if kind == 'pow':
        return f"std::pow({codegen(node[1])}, {codegen(node[2])})"
    if kind == 'bin':
        op = node[1]
        return f"({codegen(node[2])} {op} {codegen(node[3])})"
    raise ValueError(f"unknown node {node}")

if __name__ == "__main__":
    import sys
    for line in sys.stdin:
        line = line.rstrip("\n")
        if not line.strip():
            continue
        node = parse(line)
        print(codegen(node))
