def evaluate(node, env):
    kind = node[0]
    if kind == 'num':
        text = node[1]
        if text.endswith('_dp'): text = text[:-3]
        return float(text)
    if kind == 'id':
        return env['vars'][node[1]]
    if kind == 'call':
        name = node[1]
        args = [evaluate(a, env) for a in node[2]]
        return env['funcs'][name](*args)
    if kind == 'paren':
        return evaluate(node[1], env)
    if kind == 'neg':
        return -evaluate(node[1], env)
    if kind == 'pow':
        b = evaluate(node[1], env)
        e = evaluate(node[2], env)
        return b ** e
    if kind == 'bin':
        op = node[1]
        l = evaluate(node[2], env); r = evaluate(node[3], env)
        if op=='+': return l+r
        if op=='-': return l-r
        if op=='*': return l*r
        if op=='/': return l/r
    raise ValueError(node)

