        loc_funcs['zab2'] = zab2_f
        return evaluate(ffmpcc1_ast, {'vars': dict(j1=a,j2=b,j3=c,j4=d,j5=e,j6=g_), 'funcs': loc_funcs})
    def ffmpcc2_f(a,b,c,d,e,g_,*rest):
        loc_funcs = dict(funcs)
        loc_funcs['zab2'] = zab2_f
        return evaluate(ffmpcc2_ast, {'vars': dict(j1=a,j2=b,j3=c,j4=d,j5=e,j6=g_), 'funcs': loc_funcs})
    funcs.update({
